// Codegen: regenerate design-system/bundle/ — the self-contained copy of the
// design system for pasting into an external AI chat (ChatGPT/Claude/etc).
//
// Sources (canonical, hand-edited):        design-system/*.md, *.html
// Output (generated, NEVER hand-edited):   design-system/bundle/
//
// DESIGN.md gets its §3a section swapped for the embedded-base64 variant
// (assets/brand-base64-section.md) so the bundle needs no image files; every
// other file is copied verbatim with a GENERATED banner. Fails loudly if any
// source or the base64 blob is missing/truncated.
import { readFileSync, writeFileSync, mkdirSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

const DS = join(dirname(fileURLToPath(import.meta.url)), "..", "design-system");
const OUT = join(DS, "bundle");

const banner = (src) =>
  `<!-- GENERATED by scripts/gen-bundle.mjs from design-system/${src} — DO NOT EDIT. Run \`npm run gen:bundle\` to refresh. -->\n\n`;

function read(name) {
  return readFileSync(join(DS, name), "utf8");
}

/* ── DESIGN.md — swap §3a for the embedded-base64 section ─────────────── */

const design = read("DESIGN.md");
const fragment = read("assets/brand-base64-section.md");

const blob = fragment.match(/data:image\/png;base64,[A-Za-z0-9+/=]{20000,}/);
if (!blob) throw new Error("brand-base64-section.md: base64 blob missing or truncated");

// v1.0 doc: brand-mark asset spec lives in §21.2. Swap that subsection for the
// embedded-base64 fragment (retitled to keep v1.0 numbering).
const sectionRe = /### 21\.2 · Brand mark asset\n[\s\S]*?(?=\n### |\n---\n)/;
if (!sectionRe.test(design)) throw new Error("DESIGN.md: §21.2 Brand mark section not found");
if (!/## 3a · Brand mark — embedded base64/.test(fragment))
  throw new Error("brand-base64-section.md: expected §3a heading not found");

const retitled = fragment.replace(
  "## 3a · Brand mark — embedded base64",
  "### 21.2 · Brand mark — embedded base64"
);
let bundleDesign = design.replace(sectionRe, retitled.trimEnd() + "\n");

// Standalone-context prose: the bundle has no assets/ folder.
bundleDesign = bundleDesign.replaceAll("`assets/vourdev-logo.jpeg`", "the §21.2 base64 data URL");
bundleDesign = bundleDesign.replaceAll("bundle/DESIGN.md §3a", "§21.2");
bundleDesign = bundleDesign.replace(
  "# VOUR — Design System",
  "# VOUR — Design System (self-contained bundle)"
);
if (bundleDesign.includes("assets/vourdev-logo"))
  throw new Error("bundle DESIGN.md still references assets/ — substitution incomplete");

mkdirSync(OUT, { recursive: true });
writeFileSync(join(OUT, "DESIGN.md"), banner("DESIGN.md") + bundleDesign);

/* ── Verbatim copies ──────────────────────────────────────────────────── */

const COPY = [
  "MAKING_BRIEFS.md",
  "MAKING_CAROUSELS.md",
  "CUSTOM-INSTRUCTIONS.md",
  "README-FOR-AI.md",
  "TEMPLATE-editorial-v3.html",
  "EXAMPLE-editorial.html",
];
for (const name of COPY) {
  writeFileSync(join(OUT, name), banner(name) + read(name));
}

console.log(`✅ bundle regenerated (${COPY.length + 1} files) — blob ${blob[0].length.toLocaleString()} chars`);
